import '@fontsource/dm-sans/latin-400.css';
import '@fontsource/dm-sans/latin-500.css';
import '@fontsource/dm-sans/latin-600.css';
import '@fontsource/dm-sans/latin-700.css';
import '@fontsource/manrope/latin-600.css';
import '@fontsource/manrope/latin-700.css';
import '@fontsource/manrope/latin-800.css';
import './style.css';
import QRCode from 'qrcode';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bs=c=>new Intl.NumberFormat('es-BO',{style:'currency',currency:'BOB',maximumFractionDigits:2}).format((c||0)/100);
const dateNow=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/La_Paz'}).format(new Date());
let recipesData=[], recipeDraft=null;
let inventoryData=null,usersData=null,cashData=null;
let selectedDate=dateNow(), user=null, state=null, view='dashboard', cart=[], publicMode=location.pathname.startsWith('/reservar'), report=null, sound=false, audio=null, events=null, seen=null, menuDraft=null, lastRender=0;
const roles={admin:'Administración',cashier:'Caja',kitchen:'Cocina'}, kinds={soup:'Sopas',main:'Segundos',drink:'Bebidas',extra:'Extras'}, statuses={reserved:'Reservado',queued:'En espera',preparing:'Preparando',ready:'Listo para entregar',delivered:'Entregado',cancelled:'Cancelado'};
const icons={recipes:'♧',users:'♙',inventory:'▤',dashboard:'◫',pos:'▦',orders:'☷',menu:'♧',kitchen:'♨',cash:'▣',reports:'▥',share:'▧'};
async function api(path,body){const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok){if(r.status===401&&user){user=null;events?.close();render();}throw Error(data.error||'No se pudo completar la solicitud.');}return data;}
function toast(message,error=false){let box=$('#toast');if(!box){box=document.createElement('div');box.id='toast';document.body.append(box);}box.className=error?'show error':'show';box.textContent=message;clearTimeout(box.timer);box.timer=setTimeout(()=>box.className='',4500);}
function dateLabel(date){return new Intl.DateTimeFormat('es-BO',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));}
function beep(){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=740;g.gain.setValueAtTime(.12,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.65);o.start();o.stop(audio.currentTime+.65);}
async function refresh(paint=true){if(publicMode){const d=await api('/public/menu?date='+selectedDate);state={menu:d.menu,today:d.today,orders:[]};}else{state=await api('/state?date='+selectedDate);const ids=state.orders.filter(o=>o.status==='queued').map(o=>o.id);if(seen&&ids.some(id=>!seen.has(id))){beep();if(view==='kitchen')toast('Nuevo pedido en cocina');}seen=new Set(ids);}if(view==='recipes'&&!publicMode&&user?.role==='admin')recipesData=await api('/recipes?date='+selectedDate);if(view==='cash'&&!publicMode&&user?.role!=='kitchen')cashData=await api('/cash');if(paint)render();}
function connect(){events?.close();events=new EventSource('/api/events');events.onmessage=()=>{refresh(false).then(()=>{if(['dashboard','orders','kitchen','cash'].includes(view)&&!$('#modal')&&Date.now()-lastRender>300)render();else updateAvailability();}).catch(e=>toast(e.message,true));};events.onerror=()=>{$('#connection')?.classList.add('offline');};events.onopen=()=>$('#connection')?.classList.remove('offline');}
function updateAvailability(){for(const item of state.menu?.items||[]){const el=document.querySelector(`[data-stock="${item.id}"]`);if(el){el.textContent=`${item.available} disponibles`;const card=el.closest('.product-card');if(card){card.disabled=!item.available;card.classList.toggle('sold-out',!item.available);}}}}
function badge(status){return `<span class="badge ${status}"><i></i>${esc(statuses[status]||status)}</span>`;}
function empty(title,text){return `<div class="empty"><span>♧</span><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;}
function shell(content){const nav=user.role==='admin'?['dashboard','pos','orders','menu','recipes','kitchen','inventory','cash','reports','users','share']:user.role==='cashier'?['pos','orders','cash','share']:['kitchen'];const labels={recipes:'Platos y costos',dashboard:'Resumen',pos:'Punto de venta',orders:'Pedidos y reservas',menu:'Menú del día',kitchen:'Cocina',cash:'Caja y gastos',reports:'Reportes',inventory:'Inventario de bebidas',users:'Usuarios',share:'Menú y QR'};return `<aside class="sidebar"><a class="brand" href="/">◒ <span>foodsys<small>TU COCINA, EN ORDEN</small></span></a><p class="nav-caption">TU NEGOCIO</p><nav>${nav.map(n=>`<button data-view="${n}" class="nav-item ${view===n?'active':''}"><span>${icons[n]}</span>${labels[n]}${n==='orders'&&state.orders.filter(o=>o.status==='reserved').length?`<b>${state.orders.filter(o=>o.status==='reserved').length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="live-note"><i></i> Conectado a tu cocina</div><div class="profile"><div class="avatar">${esc(user.name[0])}</div><div><strong>${esc(user.name)}</strong><small>${roles[user.role]}</small></div><button data-action="logout" title="Cerrar sesión">↪</button></div></div></aside><main><header class="topbar"><div><span class="breadcrumb">Mi pensión <span>/</span> ${labels[view]}</span></div><div class="top-right"><span id="connection" class="connection"><i></i> En vivo</span><span class="today-label">${esc(dateLabel(dateNow()))}</span><button class="top-logout" data-action="logout" title="Cerrar sesión" aria-label="Cerrar sesión">↪</button></div></header><div class="content">${content}</div><footer>Foodsys <span>·</span> Hecho para servir mejor <span class="footer-right">Bolivianos (Bs) · Hora de Bolivia</span></footer></main>`;}
function heading(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function dateInput(){return `<input type="date" id="selected-date" aria-label="Fecha de trabajo" value="${selectedDate}">`;}
function metrics(){const r=state.report, orders=state.orders.filter(o=>o.status!=='cancelled'),waiting=orders.filter(o=>['queued','preparing','ready'].includes(o.status)).length;return `<div class="metrics"><article class="metric"><div>Ingresos cobrados <span class="metric-icon">↗</span></div><strong>${bs(r.income)}</strong><small>${r.count} pedidos pagados</small></article><article class="metric"><div>Resultado estimado <span class="metric-icon">⌁</span></div><strong class="${r.balance<0?'negative':''}">${bs(r.balance)}</strong><small>Ingresos menos gastos registrados</small></article><article class="metric"><div>Reservas <span class="metric-icon">▤</span></div><strong>${orders.filter(o=>o.status==='reserved').length}<em>pedidos</em></strong><small>Porciones ya apartadas</small></article><article class="metric"><div>En cocina <span class="metric-icon orange">♨</span></div><strong>${waiting}<em>pedidos</em></strong><small>En espera, preparación o listos</small></article></div>`;}
function dashboard(){return heading('VISTA GENERAL','Todo listo para servir.',`Así va tu negocio · ${esc(dateLabel(selectedDate))}`,`${dateInput()}<button class="primary" data-view="pos">＋ Nueva venta</button>`)+metrics()+`<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Disponibilidad del menú</h2><p>Cada porción cuenta. Reservas incluidas.</p></div><span class="tag">${state.menu.items.length} productos</span></div>${state.menu.items.length?`<div class="stock-list">${state.menu.items.map(i=>`<div class="stock-row"><div class="food-icon ${i.kind}">${{soup:'◡',main:'♧',drink:'♙',extra:'✧'}[i.kind]}</div><div class="stock-name"><strong>${esc(i.name)}</strong><small>${kinds[i.kind]}</small></div><div class="stock-detail"><strong class="${i.available<6?'negative':''}">${i.available}<span> / ${i.stock}</span></strong><div class="progress"><i style="width:${i.stock?i.available/i.stock*100:0}%"></i></div></div></div>`).join('')}</div>`:empty('El menú está por comenzar','Crea las porciones y los platos de este día.')}<button class="text-button" data-view="${user.role==='admin'?'menu':'pos'}">Ver menú completo →</button></section><section class="panel cash-summary"><div class="panel-heading"><div><h2>Tu día, en números</h2><p>Pagos registrados por medio de cobro</p></div></div><div class="income-orbit" style="background:${state.report.income?`conic-gradient(#57775a 0% ${state.report.cash/state.report.income*100}%, #d9c299 ${state.report.cash/state.report.income*100}% 100%)`: '#edf0e7'}"><div><span>COBRADO</span><strong>${bs(state.report.income)}</strong></div></div><div class="payment-row"><span><i class="dot green"></i>Efectivo</span><strong>${bs(state.report.cash)}</strong></div><div class="payment-row"><span><i class="dot sand"></i>QR confirmado</span><strong>${bs(state.report.qr)}</strong></div><div class="info-note">Los pagos QR se confirman manualmente después de verificar el abono en el banco.</div></section></div><section class="panel recent"><div class="panel-heading"><div><h2>Últimos pedidos</h2><p>Del primer antojo al último plato.</p></div><button class="text-button" data-view="orders">Ver todos →</button></div>${orderTable(state.orders.slice(0,5),false)}</section>`;}
function cartTotal(){return cart.reduce((a,l)=>a+l.price*l.quantity,0);}
function catalog(){const menu=state.menu;return `<div class="catalog-toolbar"><div class="segmented"><button data-category="all" class="active">Todo el menú</button><button data-category="combo">Completos</button><button data-category="soup">Sopas</button><button data-category="main">Segundos</button><button data-category="drink">Bebidas</button><button data-category="extra">Extras</button></div></div><div class="product-grid">${menu.items.some(i=>i.kind==='soup')&&menu.items.some(i=>i.kind==='main')?`<button class="product-card combo-card" data-action="combo" data-kind="combo"><div class="product-art combo"><span>◡</span><span>♧</span><b>EL FAVORITO</b></div><div class="product-body"><span class="product-type">ALMUERZO COMPLETO</span><h3>Sopa + segundo + refresco</h3><p>Vaso de refresco incluido</p><div><strong>${bs(menu.combo_price)}</strong><span class="add-circle">＋</span></div></div></button>`:''}${menu.items.map(i=>`<button class="product-card ${!i.available?'sold-out':''}" data-action="add-item" data-id="${i.id}" data-kind="${i.kind}" ${!i.available?'disabled':''}><div class="product-art ${i.kind}">${i.photo?`<img src="${esc(i.photo)}" alt="${esc(i.name)}">`:''}<span>${{soup:'◡',main:'♧',drink:'♙',extra:'✧'}[i.kind]}</span><b class="available-stock" data-stock="${i.id}">${i.available} disponibles</b></div><div class="product-body"><span class="product-type">${kinds[i.kind]}</span><h3>${esc(i.name)}</h3><p>${i.available?'Preparado para disfrutar':'Agotado por hoy'}</p><div><strong>${bs(i.price)}</strong><span class="add-circle">＋</span></div></div></button>`).join('')}</div>${!menu.items.length?empty('Aún no hay menú','Selecciona otra fecha o publica el menú de este día.'):''}`;}
function cartHTML(){return `<div class="cart-heading"><h2>${publicMode?'Tu reserva':'Nuevo pedido'}</h2><span class="tag">${cart.reduce((a,l)=>a+l.quantity,0)} ítems</span></div><div class="cart-lines">${cart.length?cart.map((l,index)=>`<div class="cart-line"><div><strong>${esc(l.label)}</strong><small>${bs(l.price)} c/u</small></div><div class="quantity"><button data-action="minus" data-index="${index}" aria-label="Quitar unidad">−</button><b>${l.quantity}</b><button data-action="plus" data-index="${index}" aria-label="Agregar unidad">＋</button></div><strong>${bs(l.price*l.quantity)}</strong></div>`).join(''):empty('Un buen almuerzo empieza aquí','Agrega platos del menú a este pedido.')}</div><form id="order-form"><label>Nombre del comensal<input name="customer" ${publicMode?'required':'value="Cliente sin nombre"'} maxlength="100" placeholder="¿Para quién es el pedido?"></label><div class="form-columns"><label>Teléfono ${publicMode?'':'(opcional)'}<input name="phone" ${publicMode?'required':''} maxlength="30" placeholder="Ej. 70000000"></label>${!publicMode?`<label>Tipo de pedido<select name="type"><option value="sale">Venta · enviar a cocina</option><option value="reservation">Reserva · apartar porciones</option></select></label>`:''}</div><label>Modalidad de consumo<select name="service_mode" required><option value="local">Consumir en el local</option><option value="takeaway">Para llevar</option></select></label><label>Nota para cocina<textarea name="note" rows="2" maxlength="500" placeholder="Sin picante, indicaciones especiales…"></textarea></label>${!publicMode?`<label>Estado del pago<select name="payment"><option value="">Pendiente de pago</option><option value="cash">Pagado en efectivo</option><option value="qr">QR · abono verificado</option></select></label>`:`<p class="info-note">La reserva aparta tus porciones. Paga en caja al recoger. No se realizan cobros en esta página.</p>`}<div class="cart-total"><span>Total del pedido</span><strong>${bs(cartTotal())}</strong></div><button class="primary full" ${!cart.length?'disabled':''}>${publicMode?'Confirmar mi reserva':'Registrar pedido'} →</button><small class="cart-footnote">${publicMode?'Guarda el número de reserva para recoger tu pedido.':'Las porciones se descuentan al registrar.'}</small></form>`;}
function pos(){return heading('PUNTO DE VENTA','Un pedido, muchas sonrisas.','Completos, platos sueltos y extras. Todo en una sola cuenta.',dateInput())+`${state.cash.closed_at&&selectedDate===state.today?'<div class="alert">La caja está cerrada. Puedes registrar reservas sin pago para otro día.</div>':''}<div class="pos-layout"><section>${catalog()}</section><aside class="cart-panel" id="cart">${cartHTML()}</aside></div>`;}
function orderActions(o){if(o.status==='cancelled'||o.status==='delivered')return '';let s='';if(user.role!=='kitchen'){if(!o.paid)s+=`<button class="small" data-action="pay" data-id="${o.id}">Cobrar</button>`;if(['reserved','queued'].includes(o.status)&&!o.paid)s+=`<button class="small danger-text" data-action="cancel" data-id="${o.id}">Anular</button>`;}const next={reserved:['queued','Enviar a cocina'],queued:['preparing','Preparar'],preparing:['ready','Marcar listo'],ready:['delivered','Entregar']}[o.status];if(next&&(user.role!=='kitchen'||o.status!=='reserved')&&(user.role!=='cashier'||o.status==='reserved'))s+=`<button class="small primary" data-action="status" data-id="${o.id}" data-status="${next[0]}">${next[1]}</button>`;return s;}
function orderTable(orders,actions=true){return orders.length?`<div class="table-scroll"><table><thead><tr><th>Pedido / comensal</th><th>Detalle</th><th>Estado</th><th>Pago</th><th>Total</th>${actions?'<th>Acciones</th>':''}</tr></thead><tbody>${orders.map(o=>`<tr><td><strong>#${String(o.id).padStart(3,'0')} · ${esc(o.customer)}</strong><small>${esc(o.phone||'Sin teléfono')} ${o.source==='public'?'· Reserva web':''}</small><small class="service-mode">${serviceLabel(o.service_mode)}</small></td><td class="order-description">${o.lines.map(l=>`<span>${l.quantity} × ${esc(l.label)}</span>`).join('')}${o.note?`<small class="order-note">Nota: ${esc(o.note)}</small>`:''}</td><td>${badge(o.status)}</td><td><span class="${o.paid?'paid':'unpaid'}">${o.paid?(o.method==='qr'?'QR confirmado':'Efectivo'):'Pendiente'}</span></td><td><strong>${bs(o.total)}</strong></td>${actions?`<td><div class="row-actions">${orderActions(o)}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay pedidos','Las ventas y reservas de la fecha aparecerán aquí.');}
function ordersPage(){return heading('PEDIDOS Y RESERVAS','Cada comensal, bajo control.','Las reservas apartan porciones. Envíalas a cocina cuando llegue el comensal.',`${dateInput()}<button class="primary" data-view="pos">＋ Nuevo pedido</button>`)+`<div class="order-filters segmented"><button data-filter="all" class="active">Todos (${state.orders.length})</button><button data-filter="reserved">Reservas</button><button data-filter="queued">En espera</button><button data-filter="preparing">Preparando</button><button data-filter="ready">Listos</button><button data-filter="delivered">Entregados</button></div><section class="panel" id="orders-table">${orderTable(state.orders)}</section>`;}
function kitchen(){const active=state.orders.filter(o=>['queued','preparing','ready'].includes(o.status));return heading('COCINA EN VIVO','Manos a la cocina.',`${active.length} pedidos por atender · ${esc(dateLabel(state.today))}`,`<button class="${sound?'primary':'secondary'}" data-action="sound">${sound?'♫ Sonido activado':'♬ Activar avisos sonoros'}</button>`)+`<div class="kitchen-board">${['queued','preparing','ready'].map(status=>`<section class="kitchen-column"><div class="column-heading"><h2><i class="dot ${status}"></i>${statuses[status]}</h2><b>${active.filter(o=>o.status===status).length}</b></div>${active.filter(o=>o.status===status).map(o=>`<article class="kitchen-ticket"><div class="ticket-top"><strong>#${String(o.id).padStart(3,'0')}</strong><small>${new Date(o.created_at).toLocaleTimeString('es-BO',{hour:'2-digit',minute:'2-digit',timeZone:'America/La_Paz'})}</small></div><h3>${esc(o.customer)}</h3><p class="service-mode">${serviceLabel(o.service_mode)}</p>${o.lines.map(l=>`<div class="ticket-line"><b>${l.quantity}</b><span>${esc(l.label)}</span></div>`).join('')}${o.note?`<div class="ticket-note">${esc(o.note)}</div>`:''}<div class="ticket-footer"><span class="${o.paid?'paid':'unpaid'}">${o.paid?'Pagado':'Pago pendiente'}</span>${orderActions(o)}</div></article>`).join('')||'<div class="kitchen-empty">✓ Todo en orden por aquí</div>'}</section>`).join('')}</div><p class="muted">Mantén esta pantalla abierta y activa el sonido en cada dispositivo. Los navegadores pueden suspender avisos en segundo plano; esta versión no incluye notificaciones con la aplicación cerrada.</p>`;}
function menuRow(item={},index=0){return `<div class="menu-row" data-id="${item.id||''}"><input aria-label="Nombre del plato" name="name" placeholder="Nombre del plato" value="${esc(item.name)}" required maxlength="100"><select aria-label="Categoría" name="kind">${Object.entries(kinds).filter(([k])=>k!=='drink').map(([k,v])=>`<option value="${k}" ${item.kind===k?'selected':''}>${v}</option>`).join('')}</select><input aria-label="Precio en Bs" type="number" name="price" min="0.01" step="0.01" value="${item.price?item.price/100:''}" required placeholder="Bs"><input aria-label="Porciones totales" type="number" name="stock" min="${item.used||0}" step="1" value="${item.stock??''}" required placeholder="Porciones"><div class="photo-editor"><input type="hidden" name="photo" value="${esc(item.photo||'')}"><img class="photo-preview" src="${esc(item.photo||'')}" alt="Foto del plato" ${item.photo?'':'hidden'}><label>Foto<input type="file" accept="image/jpeg,image/png,image/webp" data-photo></label><button type="button" class="small" data-action="remove-photo">Quitar foto</button></div><small>${item.used||0} apartadas</small><button type="button" data-action="remove-menu-row" class="icon-button" aria-label="Eliminar plato">×</button></div>`;}
function menuPage(){return heading('PLANIFICA EL SABOR','El menú de cada día.','Prepara mañana desde hoy. Las bebidas se administran en Inventario de bebidas y aparecen automáticamente en venta.',dateInput())+`<section class="panel menu-editor"><form id="menu-form"><div class="menu-settings"><label>Precio del completo (Bs)<input type="number" name="combo_price" min="0.01" step="0.01" required value="${state.menu.combo_price/100}"><small>Incluye una sopa y un segundo a elección, más un vaso de refresco automático. No registres el refresco como producto.</small></label><label class="check-label"><input type="checkbox" name="published" ${state.menu.published?'checked':''}> Publicar para reservas web</label></div><div class="menu-row menu-table-head"><span>PLATO O PRODUCTO</span><span>CATEGORÍA</span><span>PRECIO (Bs)</span><span>PRODUCCIÓN TOTAL</span><span>FOTO</span><span>COMPROMETIDO</span><span></span></div><div id="menu-rows">${state.menu.items.filter(i=>i.kind!=='drink').map(menuRow).join('')}</div><div class="editor-actions"><button type="button" class="secondary" data-action="add-menu-row">＋ Agregar producto</button><button class="primary">Guardar menú</button></div><div class="info-note">Cada completo descuenta una sopa y un segundo. El vaso de refresco ya está incluido y no requiere producción ni precio por separado. Las porciones reservadas no se vuelven a descontar al cobrar o enviar a cocina. No se puede reducir el total por debajo de lo comprometido.</div></form></section>`;}
function cashPage(){const c=cashData.cash,r=cashData.report, expected=c.opening+r.cash-r.expenses.filter(e=>e.method==='cash').reduce((s,e)=>s+e.amount,0);return heading('CAJA Y GASTOS','Cuentas claras, cada día.','Apertura automática diaria · Cierre automático a las 18:00 (Bolivia).',`<span class="badge ${c.closed_at?'cancelled':'ready'}"><i></i>Caja ${c.closed_at?'cerrada':'abierta'}</span>`)+`<div class="metrics"><article class="metric"><div>Fondo inicial</div><strong>${bs(c.opening)}</strong><small>Dinero disponible al abrir</small></article><article class="metric"><div>Ventas en efectivo</div><strong>${bs(r.cash)}</strong><small>Solo cobros de hoy</small></article><article class="metric"><div>Ventas por QR</div><strong>${bs(r.qr)}</strong><small>Abonos verificados de hoy</small></article><article class="metric"><div>Gastos totales</div><strong>${bs(r.spent)}</strong><small>Efectivo + QR / transferencia</small></article><article class="metric"><div>Efectivo esperado en caja</div><strong>${bs(expected)}</strong><small>Fondo + efectivo cobrado − gastos en efectivo</small></article></div><div class="two-columns"><section class="panel padded"><h2>Movimientos del día</h2>${user.role==='admin'?`<form id="expense-form"><label>Descripción del gasto<input name="description" placeholder="Ej. Compra de verduras" required maxlength="200"></label><div class="form-columns"><label>Importe (Bs)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Pagado con<select name="method"><option value="cash">Efectivo de caja</option><option value="qr">QR / transferencia</option></select></label></div><button class="primary" ${c.closed_at?'disabled':''}>＋ Registrar gasto</button></form>`:'<p class="muted">Los gastos los registra el administrador.</p>'}<div class="expenses-list">${r.expenses.map(e=>`<div class="payment-row"><span>${esc(e.description)}<small>${e.method==='cash'?'Efectivo':'QR / transferencia'}</small></span><strong>− ${bs(e.amount)}</strong></div>`).join('')||'<p class="muted">Aún no registraste gastos hoy.</p>'}</div></section><section class="panel padded"><h2>Arqueo y cierre</h2><p class="muted">El cierre bloquea nuevos cobros y gastos. No afecta las reservas futuras sin pago.</p><form id="opening-form"><label>Fondo inicial (Bs)<input name="amount" type="number" min="0" step="0.01" value="${c.opening/100}" required></label><button class="secondary" ${c.closed_at?'disabled':''}>Guardar fondo inicial</button></form><hr>${c.counted!==null?`<div class="info-note"><strong>Arqueo registrado</strong><p>Efectivo contado: ${bs(c.counted)}</p><p>Diferencia: ${bs(c.counted-expected)}</p><p>${esc(c.note)}</p></div>`:`<form id="close-form"><label>Efectivo contado al cierre (Bs)<input name="counted" type="number" min="0" step="0.01" required></label><label>Observaciones<textarea name="note" rows="2" maxlength="500" placeholder="Diferencias o notas del turno"></textarea></label><button class="primary">${c.closed_at?'Registrar arqueo':'Cerrar caja y registrar arqueo'}</button></form>`}${cashAuditHTML(cashData.events)}</section></div>${user.role==='admin'?cashHistoryHTML(cashData.history):''}`;}
function reportPage(){const r=report||state.report;const dates=[...new Set([...r.revenue.map(v=>v.date),...r.expenses.map(v=>v.date)])].sort();return heading('REPORTES','Decisiones con buenos números.','Flujo de cobros y gastos registrados. El resultado es estimado, no utilidad contable.')+`<section class="panel report-controls"><div class="segmented"><button data-period="day">Hoy</button><button data-period="week">Últimos 7 días</button><button data-period="month">Este mes</button></div><form id="report-form"><label>Desde<input type="date" name="from" value="${r.from}" required></label><label>Hasta<input type="date" name="to" value="${r.to}" required></label><button class="primary">Consultar</button></form></section><div class="metrics"><article class="metric"><div>Ingresos cobrados</div><strong>${bs(r.income)}</strong><small>${r.count} pedidos pagados</small></article><article class="metric"><div>Gastos registrados</div><strong>${bs(r.spent)}</strong><small>Todos los medios de pago</small></article><article class="metric"><div>Resultado estimado</div><strong class="${r.balance<0?'negative':''}">${bs(r.balance)}</strong><small>${r.balance<0?'Los gastos superan a los cobros':'Cobros menos gastos registrados'}</small></article><article class="metric"><div>Cobros en efectivo</div><strong>${bs(r.cash)}</strong><small>En el período seleccionado</small></article><article class="metric"><div>Cobros por QR</div><strong>${bs(r.qr)}</strong><small>Abonos bancarios verificados</small></article></div><section class="panel padded"><h2>Evolución por día</h2>${dates.length?`<div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Cobros</th><th>Gastos</th><th>Resultado estimado</th></tr></thead><tbody>${dates.map(date=>{const inc=r.revenue.filter(v=>v.date===date).reduce((s,v)=>s+v.amount,0),exp=r.expenses.filter(v=>v.date===date).reduce((s,v)=>s+v.amount,0);return `<tr><td>${date}</td><td>${bs(inc)}</td><td>${bs(exp)}</td><td class="${inc-exp<0?'negative':'paid'}">${bs(inc-exp)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Sin movimientos en este período','Los cobros y gastos aparecerán cuando se registren.')}<p class="info-note">Los cobros se incluyen en la fecha de pago, aunque la reserva sea para otro día. Para conocer una utilidad real debes registrar todos los costos, incluyendo ingredientes, personal, alquiler y otros gastos. No incluye valoración de inventario ni deudas pendientes.</p></section>`;}
function sharePage(){return heading('TU MENÚ, MÁS CERCA','Comparte el sabor del día.','Tus comensales pueden apartar su almuerzo desde el celular.')+`<section class="panel share-panel"><div class="qr-card"><div class="brand">◒ foodsys</div><canvas id="qr-canvas"></canvas><strong>Escanea. Elige. Reserva.</strong><small>Tu almuerzo te está esperando.</small><button class="secondary qr-download" data-action="download-qr">Descargar QR</button></div><div><span class="eyebrow">RESERVAS SIN FILAS</span><h2>Un QR para todos tus menús.</h2><p>El enlace permite elegir la fecha y consultar los menús publicados. Cada reserva aparta las porciones disponibles y llega a caja como pendiente de pago.</p><label>Enlace público<input id="share-url" readonly value="${esc(location.origin+'/reservar')}"></label><button class="primary" data-action="copy-link">Copiar enlace</button> <a class="secondary button" href="/reservar" target="_blank" rel="noopener">Ver página de reservas ↗</a><p class="info-note">Para probar en un teléfono de la misma red, abre el sistema con la IP local de tu computadora y genera aquí el QR. Para recibir reservas desde cualquier lugar necesitarás alojar el sistema en un servidor con HTTPS. localhost no es accesible desde otros dispositivos.</p></div></section>`;}
function login(){return `<div class="login-layout"><section class="login-story"><a class="brand" href="/">◒ foodsys</a><div><div class="eyebrow">MENOS ANOTAR. MÁS DISFRUTAR.</div><h1>Tu cocina,<br>en orden.</h1><p>Del menú del día a la última cuenta.<br>Todo lo que necesitas para servir mejor.</p><div class="story-plates"><div>◡</div><div>♧</div><div>♙</div></div></div><small>Hecho para pensiones, restaurantes y cocinas con mucho sabor.</small></section><section class="login-form"><div class="login-box"><span class="eyebrow">BIENVENIDO A FOODSYS</span><h2>Qué bueno verte.</h2><p class="muted">Inicia sesión para comenzar tu jornada.</p><form id="login-form"><label>Usuario<input name="username" autocomplete="username" required placeholder="Tu usuario"></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required placeholder="Tu contraseña"></label><button class="primary full">Entrar al sistema →</button><p id="login-error" role="alert" class="negative"></p></form><details class="demo-access"><summary>Accesos de prueba local</summary><p>Administrador: <b>admin / admin123</b><br>Cajero: <b>cajero / cajero123</b><br>Cocina: <b>cocina / cocina123</b></p><small>Credenciales iniciales de demostración. Revisa el README antes de exponer el sistema a Internet.</small></details><a class="public-link" href="/reservar">Soy comensal · Reservar un almuerzo ↗</a></div></section></div>`;}
function publicPage(){return `<div class="public-header"><a class="brand" href="/reservar">◒ foodsys</a><span>Un buen almuerzo te espera.</span><a href="/">Acceso personal ↗</a></div><div class="public-content">${heading('RECIÉN HECHO, PARA TI','Tu mesa empieza aquí.','Elige tu almuerzo y reserva tus porciones antes de que se terminen.',dateInput())}<div class="pos-layout"><section>${catalog()}</section><aside class="cart-panel" id="cart">${cartHTML()}</aside></div></div><footer>Reservas sujetas a disponibilidad · Pago al recoger · Hora de Bolivia</footer>`;}
function render(){lastRender=Date.now();if(!publicMode&&!user){$('#app').innerHTML=login();return;}if(!state){$('#app').innerHTML='<div class="loading">Preparando tu cocina…</div>';return;}$('#app').innerHTML=publicMode?publicPage():shell(({dashboard,pos,orders:ordersPage,menu:menuPage,recipes:recipesPage,kitchen,inventory:inventoryPage,users:usersPage,cash:cashPage,reports:reportPage,share:sharePage}[view]||dashboard)());if(view==='share'&&!publicMode)QRCode.toCanvas($('#qr-canvas'),location.origin+'/reservar',{width:220,margin:1,color:{dark:'#173e35',light:'#ffffff'}}).catch(e=>toast(e.message,true));}
function modal(html){const el=document.createElement('div');el.id='modal';el.className='modal-backdrop';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="Cerrar">×</button>${html}</section>`;document.body.append(el);el.querySelector('input,select,button:not(.modal-close)')?.focus();}
function drawCart(){const values=$('#order-form')?Object.fromEntries(new FormData($('#order-form'))):{};$('#cart').innerHTML=cartHTML();for(const [k,v] of Object.entries(values)){const el=$(`#order-form [name="${k}"]`);if(el)el.value=v;}}
function addLine(line){const key=JSON.stringify([line.kind,line.itemId,line.productId,line.soupId,line.mainId]);const old=cart.find(l=>l.key===key);if(old)old.quantity++;else cart.push({...line,key,quantity:1});drawCart();}
async function runAction(target){const a=target.dataset.action,id=Number(target.dataset.id);if(a==='edit-user'){modal(userForm(usersData.users.find(u=>u.id===id)));return;}if(a==='edit-product'){const p=inventoryData.products.find(p=>p.id===id);modal(productForm(p));return;}if(a==='logout'){await api('/logout',{});events?.close();user=null;state=null;cart=[];render();return;}if(a==='close-modal'){$('#modal')?.remove();return;}if(a==='sound'){audio ||=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();sound=!sound;beep();render();return;}if(a==='download-qr'){const link=document.createElement('a');link.download='foodsys-reservas.png';link.href=$('#qr-canvas').toDataURL();link.click();return;}if(a==='copy-link'){try{await navigator.clipboard.writeText(location.origin+'/reservar');toast('Enlace copiado');}catch{$('#share-url').select();toast('Copia el enlace seleccionado.');}return;}if(a==='add-item'){const i=state.menu.items.find(i=>i.id===id);if(i)addLine({itemId:i.productId?undefined:id,productId:i.productId,kind:i.productId?'product':'item',label:i.name,price:i.price});return;}if(a==='plus'||a==='minus'){const index=Number(target.dataset.index);cart[index].quantity+=a==='plus'?1:-1;if(cart[index].quantity<=0)cart.splice(index,1);drawCart();return;}if(a==='combo'){modal(`<h2>Tu completo, a tu gusto.</h2><p class="muted">Sopa + segundo + vaso de refresco incluido · ${bs(state.menu.combo_price)}</p><form id="combo-form">${['soup','main'].map(kind=>`<label>${kinds[kind]}<select name="${kind}Id" required><option value="">Selecciona una opción</option>${state.menu.items.filter(i=>i.kind===kind&&i.available>0).map(i=>`<option value="${i.id}">${esc(i.name)} · ${i.available} disponibles</option>`).join('')}</select></label>`).join('')}<button class="primary full">Agregar completo</button></form>`);return;}if(a==='pay'){modal(`<h2>Registrar cobro #${id}</h2><p class="muted">Si el pago es QR, verifica primero el abono en tu banco.</p><form id="pay-form" data-id="${id}"><label>Medio de pago<select name="method"><option value="cash">Efectivo recibido</option><option value="qr">QR · abono bancario verificado</option></select></label><button class="primary full">Confirmar cobro</button></form>`);return;}if(a==='cancel'){modal(`<h2>¿Anular pedido #${id}?</h2><p>Las porciones apartadas volverán a estar disponibles. Solo se pueden anular pedidos sin pago que aún no se estén preparando.</p><button class="primary full" data-action="status" data-id="${id}" data-status="cancelled">Sí, anular y liberar porciones</button>`);return;}if(a==='status'){await api(`/orders/${id}/status`,{status:target.dataset.status});$('#modal')?.remove();await refresh();toast('Pedido actualizado');return;}if(a==='add-ingredient'){$('#ingredient-rows').insertAdjacentHTML('beforeend',ingredientRow());return;}if(a==='add-service'){$('#service-rows').insertAdjacentHTML('beforeend',serviceRow());return;}if(a==='remove-cost-row'){target.closest('.cost-row').remove();updateRecipeEstimate();return;}if(a==='new-recipe'){recipeDraft=null;render();return;}if(a==='reuse-recipe'){recipeDraft=recipesData.find(r=>r.id===id);render();return;}if(a==='recipe-menu'){const r=recipesData.find(r=>r.id===id);if(selectedDate<state.today)throw Error('Para agregar al menú elige hoy o una fecha futura y reutiliza la receta.');view='menu';render();$('#menu-rows').insertAdjacentHTML('beforeend',menuRow({name:r.name,kind:r.kind,price:r.price,stock:r.portions}));toast('Plato agregado al borrador. Guarda el menú para confirmar.');return;}if(a==='add-menu-row'){$('#menu-rows').insertAdjacentHTML('beforeend',menuRow());return;}if(a==='remove-photo'){const row=target.closest('.photo-editor');row.querySelector('[name=photo]').value='';row.querySelector('.photo-preview').hidden=true;row.querySelector('[data-photo]').value='';return;}if(a==='remove-menu-row'){target.closest('.menu-row').remove();return;}}
document.addEventListener('click',async e=>{const target=e.target.closest('button,a');if(!target)return;try{if(target.dataset.view){view=target.dataset.view;if(view==='cash'){selectedDate=state.today;await refresh(false);}if(view==='recipes'){recipeDraft=null;recipesData=await api('/recipes?date='+selectedDate);}if(view==='users')usersData=await api('/users');if(view==='inventory')inventoryData=await api('/inventory');if(view==='reports')report=await api('/reports?from='+selectedDate+'&to='+selectedDate);render();return;}if(target.dataset.action){await runAction(target);return;}if(target.dataset.category){target.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===target));document.querySelectorAll('.product-card').forEach(el=>el.hidden=target.dataset.category!=='all'&&el.dataset.kind!==target.dataset.category);return;}if(target.dataset.filter){target.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===target));$('#orders-table').innerHTML=orderTable(state.orders.filter(o=>target.dataset.filter==='all'||o.status===target.dataset.filter));return;}if(target.dataset.period){const today=dateNow();let from=today;if(target.dataset.period==='month')from=today.slice(0,8)+'01';if(target.dataset.period==='week'){const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-6);from=d.toISOString().slice(0,10);}report=await api(`/reports?from=${from}&to=${today}`);render();}}catch(error){toast(error.message,true);}});
document.addEventListener('change',async e=>{if(e.target.id==='selected-date'){selectedDate=e.target.value;if(!selectedDate)return;cart=[];report=null;try{await refresh();}catch(error){toast(error.message,true);}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal')?.remove();});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{switch(form.id){case 'recipe-form':{const rows=selector=>[...form.querySelectorAll(selector)].map(row=>Object.fromEntries([...row.querySelectorAll('[name]')].map(el=>[el.name,el.value])));await api('/recipes',{...data,date:selectedDate,ingredients:rows('.ingredient-row'),services:rows('.service-row')});recipeDraft=null;await refresh();toast('Receta guardada en el historial del día');break;}case 'login-form':user=await api('/login',data);view=user.role==='admin'?'dashboard':user.role==='cashier'?'pos':'kitchen';selectedDate=dateNow();await refresh();connect();break;case 'combo-form':{const soup=state.menu.items.find(i=>i.id===Number(data.soupId)),main=state.menu.items.find(i=>i.id===Number(data.mainId));addLine({kind:'combo',soupId:soup.id,mainId:main.id,price:state.menu.combo_price,label:`Completo · ${soup.name} + ${main.name} + vaso de refresco incluido`});$('#modal').remove();break;}case 'order-form':{const order=await api(publicMode?'/public/reservations':'/orders',{...data,date:selectedDate,expectedTotal:cartTotal(),lines:cart.map(({kind,itemId,productId,soupId,mainId,quantity})=>({kind,itemId,productId,soupId,mainId,quantity}))});cart=[];await refresh();if(publicMode)modal(`<div class="success-mark">✓</div><h2>¡Tu almuerzo está reservado!</h2><p>Reserva <strong>#${String(order.id).padStart(3,'0')}</strong> para el ${selectedDate}.</p><p>Total a pagar al recoger: <strong>${bs(order.total)}</strong></p><p>Guarda una captura de este número para identificar tu pedido.</p><button class="primary full" data-action="close-modal">Entendido</button>`);else toast(`Pedido #${order.id} registrado`);break;}case 'pay-form':await api(`/orders/${form.dataset.id}/pay`,data);$('#modal').remove();await refresh();toast('Cobro registrado');break;case 'menu-form':{const items=[...$('#menu-rows').children].map(row=>({id:row.dataset.id?Number(row.dataset.id):undefined,...Object.fromEntries([...row.querySelectorAll('input[name],select[name]')].map(el=>[el.name,el.type==='checkbox'?el.checked:el.value]))}));await api('/menu',{date:selectedDate,combo_price:data.combo_price,published:data.published==='on',items});await refresh();toast('Menú guardado');break;}case 'user-edit-form':case 'user-form':{const result=await api('/users',{...data,id:data.userId,active:data.active==='on'});$('#modal')?.remove();if(result.reauthenticate){events?.close();user=null;state=null;usersData=null;cashData=null;cart=[];render();toast('Cuenta actualizada. Inicia sesión de nuevo.');break;}usersData=await api('/users');await refresh();toast('Usuario guardado');break;}case 'product-edit-form':case 'product-form':await api('/inventory/products',{...data,id:data.productId,active:data.active==='on'});$('#modal')?.remove();inventoryData=await api('/inventory');await refresh();toast('Bebida guardada');break;case 'inventory-movement-form':await api('/inventory/movements',{...data,expense:data.expense==='on'});inventoryData=await api('/inventory');await refresh();toast('Movimiento registrado');break;case 'expense-form':await api('/expenses',data);await refresh();toast('Gasto registrado');break;case 'opening-form':await api('/cash/opening',data);await refresh();toast('Fondo inicial registrado');break;case 'close-form':modal(`<h2>Confirmar arqueo</h2><p>Efectivo contado: <strong>${bs(Number(data.counted)*100)}</strong>. Al cerrar la caja se bloquearán los movimientos del día.</p><form id="confirm-close-form"><input type="hidden" name="counted" value="${esc(data.counted)}"><input type="hidden" name="note" value="${esc(data.note)}"><button class="primary full">Confirmar y guardar</button></form>`);break;case 'confirm-close-form':await api('/cash/close',data);$('#modal').remove();await refresh();toast('Arqueo registrado y caja cerrada');break;case 'report-form':report=await api(`/reports?from=${data.from}&to=${data.to}`);render();break;}}catch(error){if(form.id==='login-form'&&$('#login-error'))$('#login-error').textContent=error.message;else toast(error.message,true);}finally{if(submit)submit.disabled=false;}});
async function init(){try{if(publicMode)await refresh();else{try{user=await api('/me');}catch{}if(user){view=user.role==='admin'?'dashboard':user.role==='cashier'?'pos':'kitchen';await refresh();connect();}else render();}}catch(e){$('#app').innerHTML=`<div class="loading"><h2>No se pudo conectar</h2><p>${esc(e.message)}</p><button class="primary" onclick="location.reload()">Reintentar</button></div>`;}}init();
setInterval(()=>{if(publicMode)refresh(false).then(updateAvailability).catch(()=>{});},30000);

// Resize locally before saving; only raster images are accepted by the API.
document.addEventListener('change',async e=>{
 if(!e.target.matches('[data-photo]'))return;
 const input=e.target,file=input.files[0];if(!file)return;
 const submit=input.closest('form').querySelector('button:not([type])');submit.disabled=true;
 try{
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Elige una foto JPEG, PNG o WebP de hasta 10 MB.');
  const bitmap=await createImageBitmap(file),scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height));
  const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
  canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  const photo=canvas.toDataURL('image/jpeg',.75);if(photo.length>200000)throw Error('La foto es demasiado grande. Elige una imagen más pequeña.');
  const row=input.closest('.photo-editor');row.querySelector('[name=photo]').value=photo;const preview=row.querySelector('.photo-preview');preview.src=photo;preview.hidden=false;
 }catch(error){toast(error.message,true);}finally{input.value='';submit.disabled=false;}
});

function productForm(p={}){return `<form id="${p.id?'product-edit-form':'product-form'}"><h2>${p.id?'Editar bebida':'Nueva bebida'}</h2>${p.id?`<input type="hidden" name="productId" value="${p.id}">`:''}<label>Nombre<input name="name" required maxlength="100" value="${esc(p.name)}"></label><div class="form-columns"><label>Precio de venta (Bs)<input name="price" type="number" step=".01" min=".01" required value="${p.price?p.price/100:''}"></label><label>Alerta con estas unidades o menos<input name="minimum" type="number" min="0" max="1000000" step="1" required value="${p.minimum??5}"></label></div>${p.id?`<label class="check-label"><input type="checkbox" name="active" ${p.active?'checked':''}>Disponible para venta</label>`:`<label>Existencias iniciales<input name="stock" type="number" min="0" max="1000000" step="1" required value="0"></label>`}<div class="photo-editor beverage-photo"><input type="hidden" name="photo" value="${esc(p.photo||'')}"><img class="photo-preview" src="${esc(p.photo||'')}" alt="Foto de la bebida" ${p.photo?'':'hidden'}><label>Foto de la bebida (opcional)<input type="file" accept="image/jpeg,image/png,image/webp" data-photo><small>Puedes guardar sin foto. JPEG, PNG o WebP de hasta 10 MB; la imagen se reduce antes de guardarla.</small></label><button type="button" class="small" data-action="remove-photo">Quitar foto</button></div><button class="primary">Guardar bebida</button></form>`;}
function inventoryPage(){const data=inventoryData||{products:[],movements:[]},types={opening:'Saldo inicial',migration:'Saldo importado',receipt:'Mercadería recibida',adjustment:'Ajuste',order:'Venta / reserva',cancellation:'Anulación'};return heading('INVENTARIO DE BEBIDAS','Stock que continúa cada día.','Registra las bebidas una sola vez. Las ventas y reservas descuentan del mismo saldo.')+`<section class="panel padded"><h2>Bebidas</h2><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Precio</th><th>Disponibles</th><th>Stock mínimo</th><th>Estado</th><th></th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${bs(p.price)}</td><td><strong class="${p.stock<=p.minimum?'negative':''}">${p.stock}</strong></td><td>${p.minimum}</td><td>${p.active?(p.stock<=p.minimum?'Stock bajo':'Disponible'):'Fuera de venta'}</td><td><button class="small" data-action="edit-product" data-id="${p.id}">Editar</button></td></tr>`).join('')}</tbody></table></div><p class="info-note">Las reservas ya están descontadas. Si anulas un pedido sin pago, se liberan sus unidades. Los saldos importados de menús anteriores requieren verificar una vez el conteo físico; se conserva el último saldo, sin sumar los menús repetidos.</p></section><div class="two-columns inventory-forms"><section class="panel padded">${productForm()}</section><section class="panel padded"><h2>Entrada o ajuste de mercadería</h2><form id="inventory-movement-form"><label>Bebida<select name="productId" required><option value="">Selecciona una bebida</option>${data.products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.stock} disponibles</option>`).join('')}</select></label><label>Movimiento<select name="type"><option value="receipt">Mercadería recibida</option><option value="adjustment">Ajuste de inventario</option></select></label><div class="form-columns"><label>Fecha de recepción<input type="date" name="date" required max="${dateNow()}" value="${dateNow()}"></label><label>Cantidad<input type="number" step="1" min="-1000000" max="1000000" name="quantity" required><small>Entrada: cantidad positiva. Ajuste: positiva o negativa.</small></label></div><label>Proveedor<input name="supplier" maxlength="150"></label><label>Motivo / observación<textarea name="note" maxlength="500" rows="2"></textarea><small>Obligatorio para ajustes.</small></label><label>Costo total de la compra (Bs)<input type="number" name="cost" min="0" max="1000000" step=".01" value="0"></label><label class="check-label"><input type="checkbox" name="expense">Registrar también el pago como gasto de caja</label><label>Pagado con<select name="method"><option value="cash">Efectivo</option><option value="qr">QR / transferencia</option></select></label><p class="info-note">El stock aumenta al recibir las bebidas. Marcar gasto registra el costo una sola vez en Caja; requiere fecha de hoy y caja abierta. No lo vuelvas a registrar manualmente.</p><button class="primary">Registrar movimiento</button></form></section></div><section class="panel padded"><h2>Últimos 200 movimientos</h2><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Bebida</th><th>Movimiento</th><th>Unidades</th><th>Costo</th><th>Detalle</th></tr></thead><tbody>${data.movements.map(m=>`<tr><td>${esc(m.date)}</td><td>${esc(m.name)}</td><td>${types[m.type]||esc(m.type)}</td><td>${m.quantity>0?'+':''}${m.quantity}</td><td>${bs(m.cost)}${m.expense_id?' · gasto #'+m.expense_id:''}</td><td>${esc(m.supplier)} ${esc(m.note)} ${m.order_id?'Pedido #'+m.order_id:''}<small>${esc(m.actor)}</small></td></tr>`).join('')}</tbody></table></div></section>`;}

const timeLabel=value=>value?new Intl.DateTimeFormat('es-BO',{dateStyle:'short',timeStyle:'short',timeZone:'America/La_Paz'}).format(new Date(value)):'';
const cashActions={cash_opening:'Fondo inicial',cash_closed:'Cierre y arqueo',cash_counted:'Arqueo posterior al cierre',cash_auto_closed:'Cierre automático',cash_auto_opened:'Apertura automática'};
function cashAuditHTML(events=[]){return `<h3 class="audit-title">Responsables y movimientos de caja</h3>${events.length?events.map(e=>`<div class="payment-row"><span>${cashActions[e.action]}<small>${esc(e.actor_name)}${e.actor_username?' · '+esc(e.actor_username):''} · ${timeLabel(e.created_at)}</small></span>${e.details.amount!==undefined?`<strong>${bs(e.details.amount)}</strong>`:''}</div>`).join(''):'<p class="muted">Sin registro de responsables para esta caja anterior a la actualización.</p>'}`;}
function cashHistoryHTML(days=[]){return `<section class="panel padded recent"><h2>Control de cajas · últimos 60 días registrados</h2><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Estado</th><th>Esperado</th><th>Contado</th><th>Diferencia</th><th>Responsable / hora</th><th>Observaciones</th></tr></thead><tbody>${days.map(d=>{const closing=[...d.events].reverse().find(e=>['cash_closed','cash_counted'].includes(e.action)),automatic=d.events.find(e=>e.action==='cash_auto_closed');return `<tr><td>${d.date}</td><td>${d.closed_at?'Cerrada':'Abierta'}</td><td>${bs(d.expected)}</td><td>${d.counted===null?'Pendiente':bs(d.counted)}</td><td>${d.counted===null?'—':bs(d.counted-d.expected)}</td><td>${closing?`${esc(closing.actor_name)} · ${esc(closing.actor_username)}<small>${timeLabel(closing.created_at)}</small>`:automatic?`Sistema<small>${timeLabel(automatic.created_at)}</small>`:d.closed_at?'Sin registro anterior':'Pendiente de cierre'}</td><td>${esc(d.note)}<details><summary>Ver responsables</summary>${cashAuditHTML(d.events)}</details></td></tr>`;}).join('')}</tbody></table></div></section>`;}
function userForm(u={}){return `<form id="${u.id?'user-edit-form':'user-form'}"><h2>${u.id?'Editar usuario':'Nuevo usuario'}</h2>${u.id?`<input type="hidden" name="userId" value="${u.id}">`:''}<label>Nombre<input name="name" required maxlength="100" value="${esc(u.name)}" autocomplete="off"></label><label>Usuario de acceso<input name="username" required minlength="3" maxlength="40" pattern="[a-z0-9_.-]{3,40}" value="${esc(u.username)}" autocomplete="off"><small>Letras minúsculas, números, punto, guion o guion bajo.</small></label><label>Perfil<select name="role">${Object.entries(roles).map(([key,label])=>`<option value="${key}" ${u.role===key?'selected':''}>${label}</option>`).join('')}</select></label><label>${u.id?'Nueva contraseña (opcional)':'Contraseña'}<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="200" ${u.id?'':'required'}><small>${u.id?'Déjala vacía para conservar la actual. Cambiar contraseña o permisos cierra sus sesiones.':'Mínimo 8 caracteres.'}</small></label><label class="check-label"><input name="active" type="checkbox" ${!u.id||u.active?'checked':''}>Cuenta activa</label><button class="primary">Guardar usuario</button></form>`;}
function usersPage(){const data=usersData||{users:[],history:[]};return heading('USUARIOS','Cada acción con su responsable.','Crea una cuenta por persona. Solo el administrador puede gestionar usuarios.')+`<div class="two-columns"><section class="panel padded"><h2>Cuentas del sistema</h2><div class="table-scroll"><table><thead><tr><th>Nombre</th><th>Usuario</th><th>Perfil</th><th>Estado</th><th></th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${roles[u.role]}</td><td>${u.active?'Activo':'Desactivado'}</td><td><button class="small" data-action="edit-user" data-id="${u.id}">Editar</button></td></tr>`).join('')}</tbody></table></div><p class="info-note">Desactivar una cuenta bloquea el acceso y conserva su historial. No puedes desactivar tu propia cuenta ni dejar el sistema sin administrador. Las contraseñas no se muestran.</p></section><section class="panel padded">${userForm()}</section></div><section class="panel padded recent"><h2>Últimos 100 cambios de usuarios</h2><div class="table-scroll"><table><thead><tr><th>Fecha (Bolivia)</th><th>Responsable</th><th>Acción</th><th>Cuenta</th><th>Perfil / estado</th></tr></thead><tbody>${data.history.map(e=>{const d=e.details.after||e.details;return `<tr><td>${timeLabel(e.created_at)}</td><td>${esc(e.actor_name)}<small>${esc(e.actor_username)}</small></td><td>${e.action==='user_created'?'Creación':'Edición'}${e.details.password_changed?' · contraseña actualizada':''}</td><td>${esc(d.username)}</td><td>${roles[d.role]} · ${d.active?'Activo':'Desactivado'}</td></tr>`;}).join('')}</tbody></table></div></section>`;}

function serviceLabel(mode){return mode==='takeaway'?'Para llevar':mode==='local'?'Consumir en el local':'Consumo sin especificar';}
function ingredientRow(i={}){return `<div class="cost-row ingredient-row"><label>Ingrediente<input name="name" required maxlength="100" value="${esc(i.name)}" placeholder="Arroz, papa, tomate…"></label><label>Cantidad utilizada<input name="quantity" type="number" min=".001" max="1000000" step=".001" required value="${i.quantity??''}"></label><label>Unidad<select name="unit">${['g','kg','ml','l','unidad','docena','cucharada','cucharadita','taza'].map(u=>`<option ${i.unit===u?'selected':''}>${u}</option>`).join('')}</select></label><label>Costo de lo utilizado (Bs)<input name="cost" type="number" min="0" max="1000000" step=".01" required value="${i.cost===undefined?'':i.cost/100}"></label><button type="button" class="small" data-action="remove-cost-row" aria-label="Quitar ingrediente">×</button></div>`;}
function serviceRow(i={}){return `<div class="cost-row service-row"><label>Gasto de preparación<input name="name" required maxlength="100" placeholder="Gas, luz, agua…" value="${esc(i.name)}"></label><label>Costo de esta preparación (Bs)<input name="cost" type="number" min="0" max="1000000" step=".01" required value="${i.cost===undefined?'':i.cost/100}"></label><button type="button" class="small" data-action="remove-cost-row" aria-label="Quitar gasto">×</button></div>`;}
function recipeEstimate(total,portions,price){const unit=portions>0?total/portions:0;return `<strong>Preparación: ${bs(total)}</strong><span>Costo por porción: ${portions>0?bs(unit):'Indica las porciones'}</span><span class="${price-unit<0?'negative':''}">Margen estimado por porción: ${portions>0?bs(price-unit):'—'}</span>`;}
function updateRecipeEstimate(){const form=$('#recipe-form');if(!form)return;const total=[...form.querySelectorAll('[name=cost]')].reduce((sum,el)=>sum+Math.round(Number(el.value||0)*100),0);$('#recipe-estimate').innerHTML=recipeEstimate(total,Number(form.elements.portions.value),Number(form.elements.price.value)*100);}
document.addEventListener('input',e=>{if(e.target.closest('#recipe-form'))updateRecipeEstimate();});
function recipesPage(){const r=recipeDraft||{},ingredients=r.ingredients||[{}],services=r.services||[];return heading('PLATOS Y COSTOS','Conoce el costo de cada porción.','Guarda recetas por fecha y reutilízalas para preparar el menú del día.',dateInput())+`<section class="panel padded"><form id="recipe-form"><h2>${r.id?'Reutilizar receta · se guardará una nueva versión':'Nueva receta'}</h2><div class="form-columns"><label>Nombre del plato<input name="name" required maxlength="100" value="${esc(r.name)}"></label><label>Categoría<select name="kind">${['soup','main','extra'].map(k=>`<option value="${k}" ${r.kind===k?'selected':''}>${kinds[k]}</option>`).join('')}</select></label></div><div class="form-columns"><label>Porciones que rinde la preparación<input name="portions" type="number" min="1" max="10000" step="1" required value="${r.portions||''}"></label><label>Precio de venta por porción (Bs)<input name="price" type="number" min=".01" max="1000000" step=".01" required value="${r.price?r.price/100:''}"></label></div><h3>Ingredientes de toda la preparación</h3><p class="muted">Registra el costo de la cantidad utilizada, no el de todo el paquete. Ejemplo: 100 g de arroz que costaron Bs 0,90. Medio kilo se registra como 0,5 kg o 500 g.</p><div id="ingredient-rows">${ingredients.map(ingredientRow).join('')}</div><button class="secondary" type="button" data-action="add-ingredient">＋ Ingrediente</button><h3>Servicios y otros gastos de preparación</h3><div id="service-rows">${services.map(serviceRow).join('')}</div><button class="secondary" type="button" data-action="add-service">＋ Gas, luz, agua u otro gasto</button><label>Preparación / observaciones<textarea name="note" maxlength="1000" rows="3">${esc(r.note)}</textarea></label><div id="recipe-estimate" class="recipe-estimate">${recipeEstimate(r.total||0,r.portions||0,r.price||0)}</div><p class="info-note">El margen es precio de venta menos costo de preparación por porción; no es ganancia neta. No registra gastos en caja ni descuenta ingredientes. Registra los pagos reales y los envases en Caja y gastos. Cada guardado conserva una versión independiente en la fecha seleccionada.</p><div class="editor-actions"><button type="button" class="secondary" data-action="new-recipe">Limpiar formulario</button><button class="primary">Guardar receta del ${esc(selectedDate)}</button></div></form></section><section class="panel padded recent"><h2>Recetas guardadas · ${esc(dateLabel(selectedDate))}</h2><p class="muted">Cambia la fecha para consultar días anteriores. Reutilizar permite guardar una copia en otro día eligiendo la fecha antes de guardarla.</p>${recipesData.length?recipesData.map(recipe=>`<article class="recipe-history"><h3>${esc(recipe.name)} <small>${kinds[recipe.kind]} · ${recipe.portions} porciones · ${timeLabel(recipe.created_at)}</small></h3><div class="recipe-estimate">${recipeEstimate(recipe.total,recipe.portions,recipe.price)}<span>Venta por porción: ${bs(recipe.price)}</span></div><details><summary>Ver ingredientes y preparación</summary><ul>${recipe.ingredients.map(i=>`<li>${esc(i.name)} · ${i.quantity} ${esc(i.unit)} · ${bs(i.cost)}</li>`).join('')}${recipe.services.map(i=>`<li>${esc(i.name)} · ${bs(i.cost)}</li>`).join('')}</ul><p class="recipe-note">${esc(recipe.note)}</p></details><div class="row-actions"><button class="small" data-action="reuse-recipe" data-id="${recipe.id}">Reutilizar receta</button><button class="small" data-action="recipe-menu" data-id="${recipe.id}">Agregar al menú de esta fecha</button></div></article>`).join(''):empty('Sin recetas en esta fecha','Guarda tu primera preparación o consulta otro día.')}</section>`;}
